import Foundation

/// A dot-matrix world map: land and sea on a 2.4° grid, rasterised from Natural
/// Earth's public-domain 1:110m land polygons. Rows run north to south from
/// 82.8°N, columns west to east from 180°W; "#" is land.
enum WorldDotMap {
    static let step = 2.4
    static let northernmostLatitude = 82.8
    static let columns = 150

    /// Latitude and longitude of a dot's centre.
    static func coordinate(row: Int, column: Int) -> (latitude: Double, longitude: Double) {
        (northernmostLatitude - Double(row) * step, -180 + step / 2 + Double(column) * step)
    }

    /// Every land dot, as (row, column).
    static let landDots: [(row: Int, column: Int)] = rows.enumerated().flatMap { row, line in
        line.enumerated().compactMap { column, character in character == "#" ? (row, column) : nil }
    }

    static var rowCount: Int { rows.count }

